arguments.new_str:
protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Blog>(entity =>
    {
        // EF 9 renamed "Discriminator" to "$type". Preserve old property name for existing documents.
        entity.HasDiscriminator<string>("Discriminator");

        // EF 9 changed id format from "EntityName|KeyValue" to "EntityName-KeyValue".
        // Preserve the pipe separator for existing documents.
        entity.HasIdSeparator('|');

        // Cosmos DB does not support indexes beyond the automatic ones it creates.
        // EF 9 now throws on HasIndex(); remove the previous HasIndex call.
    });
}

